package com.example.concurrency;

import jdk.internal.vm.annotation.Contended;

public class HighThroughputCounter {

    // Thread 1 heavily increments this value
    @Contended
    private volatile long countThreadOne = 0L;

    // Thread 2 heavily increments this independent value
    @Contended
    private volatile long countThreadTwo = 0L;

    public void incrementOne() {
        countThreadOne++;
    }

    public void incrementTwo() {
        countThreadTwo++;
    }
}
